<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?>
<h1>Acceptance and clearance tracker</h1><?php if (session('message')): ?><p class="notice"><?= esc(session('message')) ?></p><?php endif ?><?php if (session('errors')): ?><ul><?php foreach(session('errors') as $error): ?><li><?= esc($error) ?></li><?php endforeach ?></ul><?php endif ?>
<section class="admin-grid"><?php foreach($metrics as $label => $count): ?><article class="admin-card"><strong><?= esc((string) $count) ?></strong><br><?= esc(str_replace('_', ' ', $label)) ?></article><?php endforeach ?></section>
<h2>Offer acceptances</h2><?php if($acceptances===[]):?><div class="empty">No applicant has responded to an offer.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Application</th><th>Offer</th><th>Status</th><th>External confirmation</th><th>Accepted</th><th>Declined</th></tr></thead><tbody><?php foreach($acceptances as $acceptance): ?><tr><td><?= esc((string) $acceptance['applicant_application_id']) ?></td><td><?= esc((string) $acceptance['admission_offer_id']) ?></td><td><?= esc($acceptance['acceptance_status']) ?></td><td><?= esc($acceptance['acceptance_fee_status']) ?></td><td><?= esc($acceptance['accepted_at'] ?? '') ?></td><td><?= esc($acceptance['declined_at'] ?? '') ?></td></tr><?php endforeach ?></tbody></table></div><?php endif?>
<h2>Clearance handoff</h2><?php foreach($clearances as $clearance): ?><article class="admin-card"><strong>Application <?= esc((string) $clearance['applicant_application_id']) ?></strong><br>Status: <?= esc($clearance['clearance_status']) ?> · External confirmation: <?= esc($clearance['acceptance_fee_status']) ?><form method="post" action="<?= site_url('tenant/admissions/acceptance/applications/'.$clearance['applicant_application_id'].'/clearance') ?>"><?= csrf_field() ?><label>Clearance status <select name="clearance_status"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="cleared">Cleared</option><option value="not_cleared">Not cleared</option></select></label><label>External acceptance confirmation <select name="acceptance_fee_status"><option value="not_required">Not required</option><option value="pending_external_confirmation">Pending external confirmation</option><option value="externally_confirmed">Externally confirmed</option><option value="waived">Waived</option></select></label><label>Staff notes <textarea name="staff_notes"></textarea></label><button>Update clearance</button></form><form method="post" action="<?= site_url('tenant/admissions/acceptance/applications/'.$clearance['applicant_application_id'].'/eligibility') ?>"><?= csrf_field() ?><button>Mark conversion eligible</button></form></article><?php endforeach ?>
<h2>Eligibility markers</h2><ul><?php foreach($eligibleMarkers as $marker): ?><li>Application <?= esc((string) $marker['applicant_application_id']) ?> — <?= esc($marker['eligibility_status']) ?> at <?= esc($marker['marked_at']) ?></li><?php endforeach ?></ul>
<?= $this->endSection() ?>
